import java.util.*;
import java.io.*;

public class Main {
    static class Val {
        double fi, se;
        Val(double a, double b) {
            this.fi = a;
            this.se = b;
        }
        Val() {
            this(0.0, 0.0);
        }
    }

    static Val Add(Val f, Val s) {
        return new Val(f.fi + s.fi, f.se + s.se);
    }

    static Val Sub(Val f, Val s) {
        return new Val(f.fi - s.fi, f.se - s.se);
    }

    static Val Mult(Val f, double w) {
        return new Val(f.fi * w, f.se * w);
    }

    static Val Div(Val f, double w) {
        return new Val(f.fi / w, f.se / w);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        double[] p = new double[n];
        for (int i = 0; i < n; i++) {
            p[i] = sc.nextDouble();
        }

        Val[] dp = new Val[1 << n];

        for (int i = 0; i < n; i++) {
            double[] p_copy = Arrays.copyOf(p, n);
            Val[] res = new Val[1 << n];
            for (int mask = 0; mask < (1 << n); mask++) {
                res[mask] = new Val(0.0, 0.0);
            }
            for (int mask = 0; mask < (1 << n); mask++) {
                if ((mask & (1 << i)) != 0) continue;
                Val sum = new Val(0.0, 0.0);
                double same = 0.0;
                for (int j = 0; j < n; j++) {
                    if (j != i && (mask & (1 << j)) != 0) {
                        same += p[j];
                        res[mask] = Add(res[mask], Mult(res[mask ^ (1 << j)], p[j]));
                    }
                }
                res[mask] = Div(sum, 1.0 - same);
            }
            Val total = new Val(1.0, 0.0);
            for (int mask = 1; mask < (1 << n); mask++) {
                if ((mask & (1 << i)) == 0) {
                    total = Add(total, res[mask]);
                }
            }
            double alp = (1.0 - total.se) / total.fi;
            Val bad = new Val(0.0, 0.0);
            for (int mask = 0; mask < (1 << n); mask++) {
                if ((mask & (1 << i)) != 0) continue;
                if (Integer.bitCount(mask) >= k) {
                    bad = Add(bad, res[mask]);
                }
            }
            double result = 1.0 - (alp * bad.fi + bad.se);
            System.out.printf("%.12f%s", result, (i + 1 == n) ? "\n" : " ");
        }
        sc.close();
    }
}
